  color: var(--ink);
}

.desk-nav-index {
  color: rgba(247, 244, 239, 0.32);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.desk-nav-btn.active .desk-nav-index {
