.desk-sidebar-foot {
  margin-top: auto;
  padding-top: 18px;
}

.desk-side-meta {
  padding: 14px 10px 4px;
  border-top: 1px solid rgba(247, 244, 239, 0.1);
  color: rgba(247, 244, 239, 0.38);
  font-size: 9px;
  line-height: 1.7;
}

.desk-workspace {
  min-height: 100vh;
  margin-left: var(--sidebar);
}

.desk-topbar {
  position: sticky;
  top: 0;
  z-index: 25;
  display: flex;
  height: var(--topbar);
  align-items: center;
