.desk-devbox {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  margin-left: auto;
  padding: 0 10px;
  border: 1px dashed rgba(228, 115, 0, 0.55);
  border-radius: 11px;
  background: rgba(228, 115, 0, 0.06);
}

.desk-devbox label {
  color: var(--ochre-dark);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.desk-devbox select {
  max-width: 140px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
}

.desk-avatar {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 50%;
  background: var(--ink);
  color: var(--paper);
  font: 600 11px/1 var(--font-display), Syne, sans-serif;
}

.desk-content {
  min-height: calc(100vh - var(--topbar));
  padding: 26px 28px 46px;
}

.crm-page {
  max-width: 1580px;
  margin: 0 auto;
