}

.crm-check-row span:last-child {
  margin-left: auto;
  color: var(--muted);
  font-size: 10px;
}

.crm-form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 13px;
}

.crm-field {
  display: grid;
  gap: 6px;
}

.crm-field.wide {
  grid-column: 1 / -1;
}

.crm-field label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.crm-textarea {
  min-height: 96px;
  padding: 11px;
  resize: vertical;
}

.crm-approval-stack {
  display: grid;
  gap: 9px;
}

.crm-approval-mini {
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--paper-2);
}

.crm-approval-mini h4 {
  margin: 10px 0 5px;
  font: 600 13px/1.35 var(--font-display), Syne, sans-serif;
}

.crm-approval-mini p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.crm-approval-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 16px;
}

.crm-metric {
  position: relative;
  min-height: 100px;
  padding: 18px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(252, 250, 246, 0.72);
}

.crm-metric-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.crm-metric strong {
  display: block;
  margin: 14px 0 7px;
  font: 600 28px/1 var(--font-display), Syne, sans-serif;
  letter-spacing: -0.04em;
}

.crm-metric small {
  color: var(--muted);
  font-size: 10px;
}

.crm-empty {
  padding: 48px 24px;
  text-align: center;
  color: var(--muted);
  font-size: 12px;
}

.crm-note {
  margin-top: 14px;
  padding: 12px 14px;
  border: 1.5px dashed rgba(228, 115, 0, 0.45);
  border-radius: 12px;
  background: rgba(228, 115, 0, 0.06);
  color: var(--ochre-dark);
  font-size: 11px;
  line-height: 1.5;
}

@media (max-width: 1100px) {
  .desk-sidebar {
    position: sticky;
    inset: auto;
    width: 100%;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 8px;
    padding: 14px;
  }

  .desk-side-context,
  .desk-nav-label,
  .desk-sidebar-foot {
    display: none;
  }

  .desk-nav {
    width: 100%;
    grid-template-columns: repeat(5, 1fr);
  }

  .desk-nav-btn {
    display: flex;
    min-height: 48px;
    flex-direction: column;
    justify-content: center;
    gap: 4px;
    padding: 6px;
    text-align: center;
  }

  .desk-nav-btn:hover {
    transform: none;
  }

  .desk-workspace {
    margin-left: 0;
  }

  .crm-split,
  .crm-cards,
  .crm-form-grid {
    grid-template-columns: 1fr;
  }
}

:root {
  --ochre: #e47300;
  --ink: #0a0908;
  --paper: #f7f4ef;
  --sand: #e8e0d4;
  --muted: #6b6560;
  --glass: rgba(255, 255, 255, 0.55);
  --glass-border: rgba(10, 9, 8, 0.08);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  color: var(--ink);
  background: var(--paper);
}

body {
  font-family: var(--font-body), system-ui, sans-serif;
  background:
    radial-gradient(1200px 600px at 10% -10%, rgba(228, 115, 0, 0.18), transparent 55%),
    radial-gradient(900px 500px at 90% 0%, rgba(10, 9, 8, 0.08), transparent 50%),
    linear-gradient(180deg, #faf7f2 0%, #efe8dc 48%, #e7dfd2 100%);
}

a {
  color: inherit;
  text-decoration: none;
}

.scene {
  perspective: 1400px;
  transform-style: preserve-3d;
}

.panel-3d {
  transform: rotateX(8deg) rotateY(-6deg);
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: transform;
}

.panel-3d:hover {
  transform: rotateX(2deg) rotateY(-2deg) translateZ(12px);
}

.panel-3d.float {
  animation: float3d 7s ease-in-out infinite;
}

@keyframes float3d {
  0%,
  100% {
    transform: rotateX(8deg) rotateY(-6deg) translateY(0);
  }
  50% {
    transform: rotateX(8deg) rotateY(-6deg) translateY(-10px);
  }
}

.pulse-bar {
  animation: pulseBar 2.4s ease-in-out infinite;
}

@keyframes pulseBar {
  0%,
  100% {
    opacity: 0.85;
  }
  50% {
    opacity: 1;
  }
}

.grain {
  pointer-events: none;
  position: fixed;
  inset: 0;
  opacity: 0.04;
  z-index: 50;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

